  `updated_at` datetime(6) DEFAULT NULL,
  `content` text NOT NULL,
  `sent_at` datetime(6) NOT NULL,
  `conversation_id` binary(16) NOT NULL,
  `receiver_id` binary(16) NOT NULL,
  `sender_id` binary(16) NOT NULL,
  `is_read` bit(1) NOT NULL,
  `client_message_id` binary(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKmtsv5ia6mh72tuwjqad4uc4j4` (`client_message_id`),
  KEY `idx_message_conversation_id` (`conversation_id`),
  KEY `idx_message_sender_id` (`sender_id`),
  KEY `idx_message_receiver_id` (`receiver_id`),
  KEY `idx_message_sent_at` (`sent_at`),
  KEY `idx_message_conversation_sent` (`conversation_id`,`sent_at`),
  CONSTRAINT `fk_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `conversation` (`id`),
  CONSTRAINT `fk_message_receiver` FOREIGN KEY (`receiver_id`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_message_sender` FOREIGN KEY (`sender_id`) REFERENCES `user` (`id`)
