DROP TABLE IF EXISTS `offer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `offer` (
  `id` binary(16) NOT NULL,
  `activity_status` enum('ACTIVE','DELETED','INACTIVE') NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `delivery_time` date NOT NULL,
  `freelancer_id` binary(16) NOT NULL,
  `posting_id` binary(16) NOT NULL,
  `price` decimal(8,2) NOT NULL,
  `status` varchar(20) NOT NULL,
  `message` text,
  `deliverable_visible` bit(1) NOT NULL,
  `delivered_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_offer_posting_id` (`posting_id`),
  KEY `idx_offer_freelancer_id` (`freelancer_id`),
  KEY `idx_offer_status` (`status`),
  KEY `idx_offer_posting_status` (`posting_id`,`status`),
  CONSTRAINT `fk_offer_freelancer` FOREIGN KEY (`freelancer_id`) REFERENCES `freelancer` (`id`),
  CONSTRAINT `fk_offer_posting` FOREIGN KEY (`posting_id`) REFERENCES `posting` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
