DROP TABLE IF EXISTS `posting`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posting` (
  `id` binary(16) NOT NULL,
  `activity_status` enum('ACTIVE','DELETED','INACTIVE') NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `budget` int NOT NULL,
  `category_id` binary(16) NOT NULL,
  `client_id` binary(16) NOT NULL,
  `deadline` date NOT NULL,
  `description` text NOT NULL,
  `status` enum('ACTIVE','CANCELLED','CLOSED','COMPLETED','IN_PROGRESS') NOT NULL,
  `title` varchar(255) NOT NULL,
  `views_count` bigint NOT NULL,
  `experience_level` enum('ENTRY','EXPERT','MID','SENIOR') NOT NULL,
  `location_id` binary(16) DEFAULT NULL,
  `photo_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_posting_client_id` (`client_id`),
  KEY `idx_posting_category_id` (`category_id`),
  KEY `idx_posting_status` (`status`),
  KEY `idx_posting_created_at` (`created_at`),
  KEY `idx_posting_deadline` (`deadline`),
  KEY `idx_posting_status_created` (`status`,`created_at`),
  KEY `fk_posting_location` (`location_id`),
  CONSTRAINT `fk_posting_client` FOREIGN KEY (`client_id`) REFERENCES `client` (`id`),
  CONSTRAINT `fk_posting_location` FOREIGN KEY (`location_id`) REFERENCES `location` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
