--
-- Table structure for table `review`
--

DROP TABLE IF EXISTS `review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review` (
  `id` binary(16) NOT NULL,
  `activity_status` enum('ACTIVE','DELETED','INACTIVE') NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `content` text NOT NULL,
  `overall_rating` int NOT NULL,
  `quality_rating` int NOT NULL,
  `timeliness_rating` int NOT NULL,
  `reviewee_id` binary(16) NOT NULL,
  `reviewer_id` binary(16) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FK897gw9qkyqyn7qmasg9wfl1rw` (`reviewee_id`),
  KEY `FKtgryf9sac5c07r4ymji4mlkyf` (`reviewer_id`),
  CONSTRAINT `FK897gw9qkyqyn7qmasg9wfl1rw` FOREIGN KEY (`reviewee_id`) REFERENCES `user` (`id`),
  CONSTRAINT `FKtgryf9sac5c07r4ymji4mlkyf` FOREIGN KEY (`reviewer_id`) REFERENCES `user` (`id`),
  CONSTRAINT `review_chk_1` CHECK (((`overall_rating` <= 5) and (`overall_rating` >= 1))),
  CONSTRAINT `review_chk_2` CHECK (((`quality_rating` <= 5) and (`quality_rating` >= 1))),
  CONSTRAINT `review_chk_3` CHECK (((`timeliness_rating` <= 5) and (`timeliness_rating` >= 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

