  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `aliases` json DEFAULT NULL,
  `description` text,
  `is_active` bit(1) NOT NULL,
  `popularity` bigint NOT NULL,
  `skill` varchar(255) NOT NULL,
  `type` enum('LANGUAGE','SOFT_SKILL','TECHNICAL','TOOL') NOT NULL,
  `category_id` binary(16) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_skill_name` (`skill`),
  KEY `idx_skill_name` (`skill`),
  KEY `idx_skill_category` (`category_id`),
  KEY `idx_skill_popularity` (`popularity`),
  KEY `idx_skill_type` (`type`),
  CONSTRAINT `fk_skill_category` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`),
  CONSTRAINT `skill_chk_1` CHECK ((`popularity` >= 0))
